export default {
	generateAndSendOTP: async () => {
		// 1. Generate OTP
		const otp = Math.floor(100000 + Math.random() * 900000).toString();

		// 2. Save ALL fields in memory
		storeValue('current_otp', otp);
		storeValue('temp_email', InputEmail.text); 
		storeValue('temp_name', InputName.text);
		storeValue('temp_pass', InputPassword.text);
		storeValue('temp_employee_id', InputEmployeeID.text); 
		storeValue('temp_ms_id', InputMSID.text);             

		// 3. Trigger email
		await send_otp_email.run({ otp: otp, email: InputEmail.text, name: InputName.text });

		showAlert('OTP sent to your SAKEC email!', 'success');
	},

	verifyAndRegister: async () => {
		// Force both to be strings and trim any invisible spaces
		const enteredOTP = String(InputOTP.text).trim();
		const storedOTP = String(appsmith.store.current_otp).trim();

		if (enteredOTP === storedOTP) {
			// Run the INSERT query
			await register_new_teacher.run();
			showAlert('Registration Successful!', 'success');
			clearStore(); 
		} else {
			// DEBUGGING ALERT: This tells you exactly what went wrong
			showAlert(`Invalid OTP. You typed: [${enteredOTP}], but memory holds: [${storedOTP}]`, 'error');
		}
	},
	loginSendOTP: async () => {
		// 1. Check if the email and password match the database
		const userRecords = await verify_teacher_login.run();

		if (userRecords && userRecords.length > 0) {
			const user = userRecords[0]; 

			// 2. Generate a new OTP
			const otp = Math.floor(100000 + Math.random() * 900000).toString();

			// 3. Save the OTP and their details temporarily
			storeValue('login_otp', otp);
			storeValue('temp_login_email', user.email);
			storeValue('temp_login_name', user.full_name);

			// 4. Send the email using your existing API!
			await send_otp_email.run({ otp: otp, email: user.email, name: user.full_name });

			showAlert('Credentials verified! OTP sent to your SAKEC email.', 'success');
		} else {
			showAlert('Invalid Email or Password.', 'error');
		}
	},

	loginVerify: async () => {
		const enteredOTP = String(InputLoginOTP.text).trim();
		const storedOTP = String(appsmith.store.login_otp).trim();

		if (enteredOTP === storedOTP) {
			// Grab the temp name/email before we clear the memory
			const finalEmail = appsmith.store.temp_login_email;
			const finalName = appsmith.store.temp_login_name;

			// Clear out the OTPs so they can't be reused
			clearStore(); 

			// Set the permanent session variables for the dashboard
			storeValue('user_email', finalEmail);
			storeValue('user_name', finalName);

			showAlert(`Welcome back, ${finalName}!`, 'success');

			// Teleport them to the Dashboard page
			// IMPORTANT: Make sure 'Dashboard' matches the exact name of your main page on the left sidebar!
			navigateTo('Dashboard', {}); 
		} else {
			showAlert(`Invalid OTP. Please try again.`, 'error');
		}
	}
}
